#!/usr/bin/env python3
from pathlib import Path
import base64, hashlib, shutil, sys, zlib

TARGETS = [
  "lib/content.ts",
  "components/portfolio-page.tsx",
  "app/globals.css",
  "tests/site.test.mjs"
]
EXPECTED = {
  "lib/content.ts": "486af3b85b09941bbe7598189a3c6715189eafdc1fc8cb3dda8257596d6e9675",
  "components/portfolio-page.tsx": "14b0c9af6e7584d8725218e42f8371c5db6864f80b5bedbab8642672efec8d32",
  "app/globals.css": "bc2a2774a10b1fc948a4ce664d92b2822f693b9f19866a7a6dba4f471a059451",
  "tests/site.test.mjs": "83ef9ec9051ee37c777cefd40b45f7d5b6921596c4e9107c6a6d82d861eeafe4"
}
PAYLOAD = {
  "lib/content.ts": "",
  "components/portfolio-page.tsx": "",
  "app/globals.css": "",
  "tests/site.test.mjs": ""
}

root = Path.cwd()
if not (root / ".git").exists() or not (root / "package.json").exists():
    raise SystemExit("ERROR: run this from the Ani-Maghakyan repository root.")

def digest(path: Path) -> str:
    return hashlib.sha256(path.read_bytes()).hexdigest()

# Refuse to overwrite an unexpected/newer source tree.
problems = []
for rel in TARGETS:
    path = root / rel
    if not path.exists():
        problems.append(f"missing: {rel}")
        continue
    got = digest(path)
    if got != EXPECTED[rel]:
        problems.append(f"changed since snapshot: {rel}\n  expected {EXPECTED[rel]}\n  current  {got}")

if problems:
    print("UI repair was NOT applied because the repo no longer matches the reviewed snapshot:")
    print("\n".join(problems))
    print("\nSend the output to ChatGPT; do not force the patch.")
    raise SystemExit(2)

backup = root / ".git" / "ani-ui-repair-v1-backup"
if backup.exists():
    shutil.rmtree(backup)
for rel in TARGETS:
    src = root / rel
    dst = backup / rel
    dst.parent.mkdir(parents=True, exist_ok=True)
    shutil.copy2(src, dst)

for rel in TARGETS:
    raw = zlib.decompress(base64.b64decode(PAYLOAD[rel])).decode("utf-8")
    path = root / rel
    path.write_text(raw, encoding="utf-8")
    print(f"updated {rel}")

print("\n✅ Ani UI Repair v1 applied.")
print("Backup: .git/ani-ui-repair-v1-backup")
print("\nNEXT: npm test")
